#!/usr/bin/env node
// LDB-A4 follow-up: stamps the client-lane 401 conformance sweep -- one
// fixture per (A-group route x client-lane 401 code: bad_signature,
// unknown_client, client_revoked, stale_timestamp, replay) -- and rewrites
// tests/conformance/manifest.ts's import list + a new `CLIENT_LANE_CASES`
// array to match. Run once, like `pick-fixtures`/`goldens -- --write`
// (README.md): its output is committed and frozen, never regenerated by
// CI. Re-run only if a NEW route joins the A-group (REQUIRED's shared
// 401/401/503 auth rows, tests/api/conformance.test.ts) -- rerunning is
// idempotent (byte-identical output) as long as ROUTES below is kept in
// sync with that table by hand.
//
// Why these five codes are (mostly) static, no live signing needed: 09
// §2.1's client lane (`src/auth/client.ts`'s `verifyClientRequest`) runs
// seven steps in order -- 1: header shape, 2: client lookup + revoked
// check, 3: clock, 4: signature, 5: nonce insert, 6: caps, 7: actor. A
// malformed header (`bad_signature`) fails at step 1, an unregistered
// client (`unknown_client`) or a revoked one (`client_revoked`) fails at
// step 2, and a timestamp far outside the +-300s window (`stale_timestamp`)
// fails at step 3 -- all three BEFORE step 4's signature check, so none of
// them need a real Ed25519 signature or a timestamp anywhere near "now":
// fully static X-Akl-* header literals, frozen forever. `replay` alone
// needs a genuine, freshly-signed request (step 5 runs only after a REAL
// signature verifies) -- a frozen one would eventually start failing on
// `stale_timestamp` instead, since the auth clock is always `systemClock`,
// never the write pipeline's `TEST_CLOCK` (tests/api/support.ts's
// `fireConformanceStep` computes it at fire time for exactly this reason).
// Its `setup` step signs a harmless `GET /v1/me` with the SAME nonce
// (`nonces`' PK is (client_id, nonce), never a route) so consuming it can
// never have a side effect on the route actually under test.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const DB_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const CONFORMANCE_DIR = join(DB_ROOT, "tests", "conformance");
const MANIFEST_PATH = join(CONFORMANCE_DIR, "manifest.ts");

const CONFORMANCE_CLIENT_ID = "conformance-client-1";
const REVOKED_CLIENT_ID = "conformance-client-revoked-1";
const UNKNOWN_CLIENT_ID = "conformance-client-never-registered-1";
const STATIC_ACTOR = "899999999999999901";
const REPLAY_ACTOR = "899999999999999902";
const STALE_TS = "1700000000"; // 2023-11-14T22:13:20Z -- always >300s stale from here on out

function b64url(bytes) {
  return Buffer.from(bytes).toString("base64url");
}

const NONCE_16 = b64url(new Uint8Array(16));
const NONCE_SHORT = b64url(new Uint8Array(3)); // 4 chars -> 3 bytes, not 16 -> malformed shape
const SIG_64 = b64url(new Uint8Array(64));

// (folder, verb, method, routeTemplate, concretePath) -- one row per
// A-group route in tests/api/conformance.test.ts's REQUIRED table (every
// `...A` spread there), same order that file lists them in.
const ROUTES = [
  ["me", "", "GET", "/v1/me", "/v1/me"],
  ["layouts-write", "post", "POST", "/v1/layouts", "/v1/layouts"],
  ["layouts-write", "put", "PUT", "/v1/layouts/:ref", "/v1/layouts/01ARZ3NDEKTSV4RRFFQ69G5FAV"],
  ["layouts-write", "patch", "PATCH", "/v1/layouts/:ref", "/v1/layouts/01ARZ3NDEKTSV4RRFFQ69G5FAV"],
  ["layouts-write", "delete", "DELETE", "/v1/layouts/:ref", "/v1/layouts/01ARZ3NDEKTSV4RRFFQ69G5FAV"],
  ["layouts-write", "restore", "POST", "/v1/layouts/:ref/restore", "/v1/layouts/01ARZ3NDEKTSV4RRFFQ69G5FAV/restore"],
  ["layouts-write", "transfer", "POST", "/v1/layouts/:ref/transfer", "/v1/layouts/01ARZ3NDEKTSV4RRFFQ69G5FAV/transfer"],
  ["layouts-like", "put", "PUT", "/v1/layouts/:ref/like", "/v1/layouts/01ARZ3NDEKTSV4RRFFQ69G5FAV/like"],
  ["layouts-like", "delete", "DELETE", "/v1/layouts/:ref/like", "/v1/layouts/01ARZ3NDEKTSV4RRFFQ69G5FAV/like"],
  ["admin-admins", "get", "GET", "/v1/admin/admins", "/v1/admin/admins"],
  ["admin-admins", "post", "POST", "/v1/admin/admins", "/v1/admin/admins"],
  ["admin-admins", "delete", "DELETE", "/v1/admin/admins/:user_id", "/v1/admin/admins/800000000000000099"],
  ["admin-import", "pause", "POST", "/v1/admin/import/pause", "/v1/admin/import/pause"],
  ["admin-import", "resume", "POST", "/v1/admin/import/resume", "/v1/admin/import/resume"],
  ["admin-import", "tick", "POST", "/v1/admin/import/tick", "/v1/admin/import/tick"],
  ["admin-diff", "tick", "POST", "/v1/admin/diff/tick", "/v1/admin/diff/tick"],
  ["admin-clients", "get", "GET", "/v1/admin/clients", "/v1/admin/clients"],
  ["admin-clients", "post", "POST", "/v1/admin/clients", "/v1/admin/clients"],
  ["admin-clients", "delete", "DELETE", "/v1/admin/clients/:id", "/v1/admin/clients/conformance-client-nonexistent"],
  ["webhooks", "post", "POST", "/v1/webhooks", "/v1/webhooks"],
  ["webhooks", "get", "GET", "/v1/webhooks", "/v1/webhooks"],
  ["webhooks", "delete", "DELETE", "/v1/webhooks/:id", "/v1/webhooks/nonexistent"],
  ["admin-drill", "post", "POST", "/v1/admin/drill", "/v1/admin/drill"],
  ["admin-health", "", "GET", "/v1/admin/health", "/v1/admin/health"],
  // X4 follow-up 3: appended at the END, not inserted alongside admin-diff
  // above -- every earlier row's `replayNonce` is derived from its own
  // array INDEX (`i`), so inserting a new route in the middle would shift
  // every later row's nonce and silently invalidate its already-committed
  // fixture. Keep future additions appended here too.
  ["admin-nightly", "tick", "POST", "/v1/admin/nightly/tick", "/v1/admin/nightly/tick"],
  // M1 (LDB-I10, design/layout-db/17-magic-ownership.md §4): same shape as
  // admin-import/tick above.
  ["admin-import", "strip-cmini-magic", "POST", "/v1/admin/import/strip-cmini-magic", "/v1/admin/import/strip-cmini-magic"],
];

if (ROUTES.length !== 26) throw new Error(`expected 26 A-group routes, got ${ROUTES.length}`);

function pascal(s) {
  return s
    .replaceAll("/", "-")
    .replaceAll("_", "-")
    .split("-")
    .filter(Boolean)
    .map((p) => p[0].toUpperCase() + p.slice(1))
    .join("");
}

function fileStub(verb, code) {
  return verb ? `${verb}-401-${code}` : `401-${code}`;
}

function caseId(folder, verb, code) {
  return `${folder}/${fileStub(verb, code)}`;
}

function importVar(folder, verb, code) {
  return "cl" + pascal(folder) + pascal(verb) + pascal(code);
}

function staticFixture(clientId, nonce, error, message, omitSkew = false) {
  const response = {
    status: 401,
    headers: { "Content-Type": "application/json", "WWW-Authenticate": "Bearer" },
    body: { error, message },
  };
  if (omitSkew) response.omitBodyKeys = ["skew"];
  return {
    headers: {
      "X-Akl-Client": clientId,
      "X-Akl-Timestamp": STALE_TS,
      "X-Akl-Nonce": nonce,
      "X-Akl-Actor": STATIC_ACTOR,
      "X-Akl-Signature": SIG_64,
    },
    response,
  };
}

const imports = [];
const kases = [];

for (const [i, [folder, verb, method, routeTemplate, path]] of ROUTES.entries()) {
  mkdirSync(join(CONFORMANCE_DIR, folder), { recursive: true });
  const replayNonce = b64url(Buffer.from((i + 1).toString(16).padStart(32, "0"), "hex"));

  const mutations = [
    ["bad_signature", () => staticFixture(CONFORMANCE_CLIENT_ID, NONCE_SHORT, "bad_signature", "the client signature is missing or invalid")],
    ["unknown_client", () => staticFixture(UNKNOWN_CLIENT_ID, NONCE_16, "unknown_client", "unknown client")],
    ["client_revoked", () => staticFixture(REVOKED_CLIENT_ID, NONCE_16, "client_revoked", "this client has been revoked")],
    ["stale_timestamp", () => staticFixture(CONFORMANCE_CLIENT_ID, NONCE_16, "stale_timestamp", "request timestamp is outside the accepted window", true)],
  ];

  for (const [code, build] of mutations) {
    const { headers, response } = build();
    const stub = fileStub(verb, code);
    const id = caseId(folder, verb, code);
    const varName = importVar(folder, verb, code);
    const fixture = { request: { method, path, headers }, response };
    writeFileSync(join(CONFORMANCE_DIR, folder, `${stub}.json`), JSON.stringify(fixture, null, 2) + "\n");
    imports.push(`import ${varName} from "./${folder}/${stub}.json" with { type: "json" };`);
    kases.push(`  kase("${id}", "${routeTemplate}", ${varName}, true),`);
  }

  // `replay`: a live-signed pair sharing one nonce, never frozen headers.
  const stub = fileStub(verb, "replay");
  const id = caseId(folder, verb, "replay");
  const varName = importVar(folder, verb, "replay");
  const fixture = {
    request: {
      method,
      path,
      signed: { actor: REPLAY_ACTOR, nonce: replayNonce },
      setup: [{ method: "GET", path: "/v1/me", signed: { actor: REPLAY_ACTOR, nonce: replayNonce } }],
    },
    response: {
      status: 401,
      headers: { "Content-Type": "application/json", "WWW-Authenticate": "Bearer" },
      body: { error: "replay", message: "nonce already used" },
    },
  };
  writeFileSync(join(CONFORMANCE_DIR, folder, `${stub}.json`), JSON.stringify(fixture, null, 2) + "\n");
  imports.push(`import ${varName} from "./${folder}/${stub}.json" with { type: "json" };`);
  kases.push(`  kase("${id}", "${routeTemplate}", ${varName}, true),`);
}

console.log(`Generated ${imports.length} fixtures across ${ROUTES.length} routes.`);

let manifest = readFileSync(MANIFEST_PATH, "utf8");

const IMPORT_MARKER = 'import adminDiffTick503IdentityUnavailable from "./admin-diff/tick-503-identity_unavailable.json" with { type: "json" };\n';
if (!manifest.includes(IMPORT_MARKER)) throw new Error("import marker not found");
manifest = manifest.replace(
  IMPORT_MARKER,
  IMPORT_MARKER +
    "\n// LDB-A4 follow-up: the client lane's own five 401 codes (bad_signature,\n" +
    "// unknown_client, client_revoked, stale_timestamp, replay), swept over\n" +
    "// every A-group route (10 C1, 09 §2.1) -- generated by\n" +
    "// scripts/gen-client-lane-sweep.mjs, one fixture template stamped per\n" +
    "// route x code rather than hand-written.\n" +
    imports.join("\n") +
    "\n",
);

const CASES_END = "  ...T6_CASES,\n];\n";
if (!manifest.includes(CASES_END)) throw new Error("CASES-end marker not found");
manifest = manifest.replace(CASES_END, "  ...T6_CASES,\n\n  ...CLIENT_LANE_CASES,\n];\n");

const CASES_DECL = "export const CASES: ConformanceCase[] = [";
if (!manifest.includes(CASES_DECL)) throw new Error("CASES declaration not found");
const constBlock =
  "// LDB-A4 follow-up: the client lane's own five 401 codes, swept over\n" +
  "// every route in the A-group (REQUIRED's shared 401/401/503 auth rows,\n" +
  "// conformance.test.ts). `bad_signature`/`unknown_client`/`client_revoked`/\n" +
  "// `stale_timestamp` fail inside `verifyClientRequest` before any DB\n" +
  "// write (steps 1-3, src/auth/client.ts) -- fully static headers, no\n" +
  "// per-run drift. `replay` alone needs a live signature (a frozen one\n" +
  "// would eventually fail on `stale_timestamp` instead, since the auth\n" +
  "// clock is always `systemClock`, never `TEST_CLOCK`) -- its `setup` step\n" +
  "// signs a harmless `GET /v1/me` with the SAME nonce (nonces are keyed\n" +
  "// only by (client_id, nonce), never by route) so consuming it can never\n" +
  "// have a side effect on the route actually under test.\n" +
  "export const CLIENT_LANE_CASES: ConformanceCase[] = [\n" +
  kases.join("\n") +
  "\n];\n\n";
manifest = manifest.replace(CASES_DECL, constBlock + CASES_DECL);

writeFileSync(MANIFEST_PATH, manifest);
console.log("manifest.ts updated.");
